; pairs.asm -- chapter 7: sixteen bits from two registers
; generated by gen07.py
        INCLUDE "msx.inc"
        OUTPUT "pairs.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
init:   di
        ld sp, SYS_AREA
        ld hl, $00FF
        ld de, 0
        push de
        pop af                  ; A = 0 and F = 0: every flag clear
        inc hl
        push af
        ld (RESULTS + 0), hl      ; HL afterwards
        pop de
        ld a, e
        ld (RESULTS + 2), a   ; and F
        ld hl, $00FF
        ld de, 0
        push de
        pop af                  ; A = 0 and F = 0: every flag clear
        inc l
        push af
        ld (RESULTS + 3), hl      ; HL afterwards
        pop de
        ld a, e
        ld (RESULTS + 5), a   ; and F
stop:   jr stop
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
